{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Azure Function App does not have public network access disabled. This could expose the application to unauthorized access over the public internet."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Azure Function App does not enforce HTTPS-only access. Allowing HTTP access could expose sensitive data to interception."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key

  site_config {
    application_stack {
      node_version = "18"
    }
    ftps_state = "Disabled" # Disable FTP to enhance security
    http2_enabled = true     # Enable HTTP/2 for better performance and security
    use_32_bit_worker_process = false # Use 64-bit worker process for better performance and security
  }

  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }

  https_only = true # Enforce HTTPS-only access
  public_network_access_enabled = false # Disable public network access
}",
  "fix_summary": "Disabled public network access and enforced HTTPS-only access for the Azure Function App. Additionally, added minor security enhancements such as disabling FTP, enabling HTTP/2, and using a 64-bit worker process."
}
